<?php
require __DIR__.'/config.php';require __DIR__.'/database_upgrade.php';try{$p=db();apply_database_upgrade($p);}catch(Throwable $e){exit('Directory unavailable.');}if(!is_role('customer')){flash('Customer access is required.','error');redirect('index.php?page=login');}$u=user();
$q=$p->prepare('SELECT b.*,c.name category FROM favorites f JOIN businesses b ON b.id=f.business_id JOIN categories c ON c.id=b.category_id WHERE f.user_id=? ORDER BY f.created_at DESC LIMIT 6');$q->execute([$u['id']]);$favorites=$q->fetchAll();$q=$p->prepare('SELECT i.*,b.name business FROM inquiries i JOIN businesses b ON b.id=i.business_id WHERE i.user_id=? ORDER BY i.created_at DESC LIMIT 8');$q->execute([$u['id']]);$inquiries=$q->fetchAll();$q=$p->prepare('SELECT COUNT(*) FROM messages WHERE receiver_id=? AND read_at IS NULL');$q->execute([$u['id']]);$unreadMessages=(int)$q->fetchColumn();$new=$p->query("SELECT b.*,c.name category FROM businesses b JOIN categories c ON c.id=b.category_id WHERE b.status='approved' ORDER BY b.created_at DESC LIMIT 6")->fetchAll();$categories=$p->query('SELECT id,name FROM categories WHERE active=1 ORDER BY name LIMIT 8')->fetchAll();
