<?=e($f[1])?>"><?=e($f[0])?></div><?php endif?><section class="panel"><h2>New businesses</h2><div class="cards"><?php foreach($new as $b):?><article class="business-card"><div class="card-content"><span class="pill"><?=e($b['category'])?></span><h3><?=e($b['name'])?></h3><p><?=e($b['description'])?></p><a class="text-link" href="index.php?page=business&id=<?=$b['id']?>">View business →</a></div></article><?php endforeach?></div></section><section class="panel" id="saved"><h2>Saved businesses</h2><div class="cards"><?php foreach($favorites as $b):?><article class="business-card"><div class="card-content"><span class="pill"><?=e($b['category'])?></span><h3><?=e($b['name'])?></h3><p>📍 <?=e($b['barangay'])?>, Davao City</p><a class="text-link" href="index.php?page=business&id=<?=$b['id']?>">View business →</a></div></article><?php endforeach;if(!$favorites):?><p class="empty">No favorites yet. Save businesses from their profile to find them here.</p><?php endif?></div></section><section class="panel"><h2>My inquiry history</h2><p class="inquiry-help">Every inquiry opens a private message thread. Owner replies appear in <a href="messages.php">Messages</a>.</p><div class="table-wrap"><table><tr><th>Business</th><th>Subject</th><th>Status</th><th>Sent</th></tr><?php foreach($inquiries as $i):?><tr><td><?=e($i['business'])?></td><td><?=e($i['subject'])?></td><td><span class="status <?=e($i['status'])?>"><?=e($i['status'])?></span></td><td><?=e(date('M j, Y g:i A',strtotime($i['created_at'])))?></td></tr><?php endforeach;if(!$inquiries):?><tr><td colspan="4">No inquiries yet. Contact a business from its profile when you have a question.</td></tr><?php endif?></table></div></section></main></body></html>
